"""Integrate the bounded revision25 experiment into the preserved revision24 chapter."""
from pathlib import Path
import re
import pandas as pd

P=Path(__file__).resolve().parent; C=P.parent/'chapter2'
source=C/'history/revision24/Chapter_2_Empirical_Analysis.md'
paras=source.read_text().split('\n\n');assert len(paras)==155
changes={};before={};after={}
s=pd.read_csv(P/'results/scores.csv')

def dec(x,n=4):return f'{x:.{n}f}'.replace('.',',')
def table(configs):
    labels=['Модель']
    for h in [1,4]:
        for cfg in configs:labels.append(f'{cfg}, $h={h}$')
    rows=['| '+' | '.join(labels)+' |','| --- | ---: | ---: | ---: | ---: |']
    for m in ['HIST','AR','AR_ESI','AR_ESI_NFCI','AR_ESI_ANFCI']:
        values=[m.replace('_',' + ')]
        for h in [1,4]:
            for cfg in configs:
                row=s.query("variant=='expanding' and config==@cfg and h==@h and model==@m").iloc[0]
                values.append(dec(row.mean_loss))
        rows.append('| '+' | '.join(values)+' |')
    return '\n'.join(rows)

changes[19]='При этом отсутствие будущей информации не означает одинаковой свежести всех предикторов. ESI отражает первые два месяца квартала, тогда как исходные американские агрегаты включают допустимые недели почти до его окончания. Поэтому сравнение с AR + ESI затрагивает и содержание финансовой информации, и её временной охват. Для проверки второй составляющей дополнительно рассчитаны американские агрегаты только за первые два месяца. Сохраняются прежние исторические снимки и дата прогноза; сопоставляется состав включённых недель. Такая проверка ограничивает возможное объяснение выигрыша данными третьего месяца, но не уравнивает все даты публикации и пересмотров разнородных источников. Результаты приведены в параграфе 2.4.'

before[68]=[
    'Две дополнительные модификации направлены на конкретные слабости исходной процедуры. Первая ограничивает наблюдения NFCI и ANFCI первыми двумя месяцами каждого квартала: дата недели плюс семь дней должна быть не позже конца второго месяца. Применяется прежнее среднее недельных значений. Агрегаты пересчитываются во всех обучающих строках и в текущем прогнозном наборе; европейские показатели, цели и состав строк остаются прежними. Обозначение Q соответствует исходному квартальному охвату, M2 — сокращённому. Это проверка роли временного охвата, а не перенос даты выпуска прогноза на месяц раньше.[^26]',
    'Вторая модификация проверяет роль экстраполяции по текущему лаговому росту. Если этот рост выходит за диапазон значений в допустимом обучающем окне, в прогноз подставляется ближайшая граница диапазона:',
    '$$\n\\widetilde g_{t-1}^{(d_t)}=\\min\\left\\{\\max\\left[g_{t-1}^{(d_t)},\\min_{s\\in\\mathcal T_{t,h}}g_{s-1}^{(d_t)}\\right],\\max_{s\\in\\mathcal T_{t,h}}g_{s-1}^{(d_t)}\\right\\}.\n\\tag{2.10}\n$$',
    'Здесь используются только значения из текущего обучающего окна; при скользящей схеме — из последних 52 допустимых строк. Оценённые коэффициенты и обучающие ответы не меняются. Правило одинаково применяется к AR, AR + ESI и обоим американским расширениям; HIST от текущего регрессора не зависит. Внутри диапазона прогноз остаётся прежним. Обозначение raw означает исходный рост, clip_g — применение (2.10). Четыре сочетания Q_raw, M2_raw, Q_clip_g и M2_clip_g рассматриваются в расширяющейся и скользящей схемах. Тем самым отдельно проверяются временной охват, реакция на экстремальный рост и их сочетание.',
    'Правило ограничения предложено после обнаружения проблемной экстраполяции. До новых расчётов были зафиксированы четыре конфигурации, две схемы обучения и набор сравнений; дополнительные пороги и окна по качеству не выбирались. Однако такая последовательность не превращает проверку в независимое подтверждение заранее разработанной прогнозной стратегии. Её назначение — установить, сохраняется ли дополнительный выигрыш индекса после одного прозрачного изменения европейской части модели. Исходный эксперимент остаётся главным, а все четыре конфигурации публикуются полностью.'
]
changes[68]='Разности средних потерь расширяющегося окна интерпретируются описательно. Вспомогательное статистическое сравнение относится к фиксированному окну 52 квартала: подход Giacomini–White с постоянным инструментом и оценкой долговременной дисперсии Bartlett HAC. Постоянный инструмент задаёт сравнение средних потерь, а не равенства качества во всех состояниях экономики. Для пяти пар в каждой из четырёх конфигураций рассчитываются разности, 95%-е асимптотические интервалы и двусторонние p-значения. На основном горизонте двадцать сравнений образуют единую семью с поправкой Holm; четырёхквартальный горизонт образует отдельную дополнительную семью. Основная длина усечения HAC — четыре квартала, проверка чувствительности — восемь. Результаты не переносятся на расширяющееся окно и не заменяют специальную процедуру для вложенных квантильных моделей с пересмотрами. Полная матрица сравнений и интервалы с поправкой Bonferroni приведены в приложении к главе.[^16][^17][^26]'
changes[69]='Исследование развивалось последовательно: ANFCI был добавлен после первоначального анализа NFCI, а проверки временного охвата и экстраполяции — после получения основного результата. Каждый этап сохраняет свой протокол и расчёты. Такая история позволяет проследить исследовательские решения, но не даёт оснований представлять весь проект как предварительно зарегистрированный до знакомства с данными. Сначала рассматривается исходный эксперимент, затем — чувствительность его выводов к явно обозначенным изменениям.'
changes[96]=paras[96].replace('Итак, основной эксперимент','Исходный эксперимент').replace('обучающего окна и версии данных.','обучающего окна, версии данных, временного охвата индексов и реакции на экстремальный рост.')

changes[98]='Проверки устойчивости устанавливают, какие свойства прогнозов сохраняются при изменении процедуры, а какие связаны с конкретными наблюдениями. Сначала рассматриваются состав оценочных дат, обучающее окно и версия данных. Затем проверяются временной охват американских индексов и ограничение экстраполяции по лаговому росту. При исключении даты из оценки прогнозы не переоцениваются; при изменении обучения или состава предикторов формируется новая процедура. Эти операции имеют разный смысл, поэтому их результаты представлены раздельно.'
changes[119]='Отдельная локальная проверка относится к округлённым темпам ВВП за I квартал 2022 года. В исходном четырёхмодельном эксперименте выполнены 144 сценария: девять сочетаний округления, два горизонта, два окна и четыре модели. При замене только прогноза для исходного квартала 2022Q2 максимальное изменение полной средней потери составляет около 0,000051. В этом ограниченном сравнении округление не объясняет основные разрывы качества. ANFCI и переоценивание последующих дат проверкой не охвачены; поэтому результат не является общей верхней границей влияния округления. Конкретные значения сценариев и границы проверки приведены в приложении.[^23]'

after[119]=[
    'Проверка временного охвата позволяет уточнить объяснение исходного выигрыша. После ограничения американских индексов первыми двумя месяцами все 59 информационных наборов остаются полными; текущие агрегаты включают семь или восемь недель. Для оценки сохраняются те же 58 и 55 дат и точно те же обучающие строки. В таблице 2.6 показаны исходный квартальный и сокращённый охваты при неизменном правиле использования лагового роста.',
    'Таблица 2.6. Средняя потеря при ограничении американских индексов первыми двумя месяцами',
    table(['Q_raw','M2_raw']),
    'Примечание. Расширяющееся окно; Q_raw — исходная конфигурация, M2_raw — сокращённый временной охват американских индексов. HIST, AR и AR + ESI не меняются. Исторические версии, оценочный факт и даты прогнозов прежние. Источник: расчёты автора.[^26]',
    'При $h=1$ M2-расширения с NFCI и ANFCI уменьшают потерю европейской базы соответственно на 5,4% и 7,5%; при $h=4$ — на 27,8% и 42,8%. Следовательно, наличие наблюдений третьего месяца не является необходимым условием среднего выигрыша в этом эксперименте. Вместе с тем ограничение охвата не устраняет прежнюю слабость: после удаления только прогноза с исходным кварталом 2020Q4 из оценки выигрыш над AR + ESI исчезает для обоих индексов на обоих горизонтах. Оба M2-расширения также уступают HIST. Вывод относится к исключённым недельным наблюдениям; влияние всех пересмотров и различий публикационного календаря здесь не разделяется.',
    'Проверка ограничения роста отвечает на более узкий вопрос: сохраняется ли преимущество финансового показателя, если европейская регрессия меньше реагирует на значения роста далеко за диапазоном обучения? Правило (2.10) срабатывает лишь на трёх исходных кварталах при $h=1$ — 2020Q2, 2020Q3 и 2020Q4. При $h=4$ к ним добавляются 2021Q3 и 2021Q4. Этот набор одинаков в расширяющейся и скользящей схемах, хотя сами обучающие границы различаются. Даты не удаляются; оцениваются все прежние прогнозы.',
    'Таблица 2.7. Средняя потеря при ограничении текущего лагового роста обучающим диапазоном',
    table(['Q_clip_g','M2_clip_g']),
    'Примечание. Расширяющееся окно. В обеих конфигурациях применяется (2.10); в M2_clip_g дополнительно сокращён охват американских индексов. Для каждой модели используются границы общего обучающего окна соответствующего горизонта. HIST остаётся неизменным. Источник: расчёты автора.[^26]',
    'Потеря AR + ESI снижается с 1,8008 до 1,3266 при $h=1$ и с 1,5006 до 0,7284 при $h=4$, то есть на 26,3% и 51,5%. Теперь оба американских расширения имеют большую среднюю потерю, чем эта база, как при квартальных, так и при двухмесячных агрегатах. В объединённой M2_clip_g конфигурации отставание NFCI и ANFCI от AR + ESI составляет соответственно 7,2% и 6,1% на коротком горизонте, 48,9% и 16,5% — на длинном. Положительная разность сохраняется после любого одиночного исключения оценочной даты в расширяющейся схеме. Таким образом, результат уже не сводится к одной удалённой дате: при сохранении всей выборки прозрачное изменение реакции на лаговый рост устраняет средний выигрыш обоих индексов над европейской базой.',
    'На ключевой дате 15 января 2021 года изменение видно непосредственно. Одноквартальный прогноз AR + ESI уменьшается с 28,05 до 0,61 при факте −1,15; четырёхквартальный — с 46,17 до 3,71 при факте 4,54. Для этого не требуется дополнительная американская информация. Такой результат поддерживает объяснение, согласно которому заметная часть прежнего относительного выигрыша компенсировала неустойчивую экстраполяцию выбранной базы. Он не доказывает отсутствия полезной финансовой информации при других спецификациях или режимах.',
    'Изменяется и место простого исторического ориентира. После ограничения роста AR + ESI имеет на 2,0% меньшую потерю, чем HIST, при $h=1$; при $h=4$ наименьшая потеря в расширяющейся схеме принадлежит AR — 0,7052 против 0,7473 у HIST. В скользящем окне ограниченный AR также лучше HIST на длинном горизонте, тогда как на коротком HIST сохраняет первое место. Поэтому прежний вывод о лучшем результате HIST необходимо относить к исходным процедурам и к сравнению с американскими расширениями. Небольшое среднее преимущество новых европейских процедур описывается как результат этой диагностической проверки; отдельная значимость их выигрыша над HIST здесь не заявляется.',
    'Ограничение роста также не решает все проблемы нижнего квантиля. В M2_clip_g частоты нарушений для NFCI составляют 25,9% и 43,6%, для ANFCI — 12,1% и 16,4% на двух горизонтах. Снижение крупных ошибок и близость частоты к 10% остаются разными свойствами. Кроме того, минимум и максимум прошлой выборки не являются экономическими пределами будущего роста. При новом режиме ограничение способно сгладить содержательный экстремальный сигнал. Поэтому улучшение европейской базы в этой ретроспективной проверке обосновывает диагностику экстраполяции, но ещё не выбор универсального эксплуатационного правила.',
    'Переход к скользящему окну подтверждает основное направление эффекта ограничения: на полной выборке обе американские модели уступают ограниченной AR + ESI при обоих охватах и горизонтах. Для ANFCI этот знак сохраняется после каждого одиночного исключения. Для NFCI при $h=1$ два исключения меняют знак; значит, полная устойчивость этого конкретного сравнения к любой отдельной дате не достигнута. Подробная матрица потерь, частот и влияния дат вынесена в приложение.'
]

changes[120]=paras[120].replace('Результаты за 2022–2025 годы', 'Результаты исходной конфигурации Q_raw за 2022–2025 годы')
changes[121]=paras[121].replace('ни одна из пяти моделей', 'ни одна из пяти исходных моделей')

changes[122]='Статистическая часть теперь охватывает все двадцать заранее перечисленных парных сравнений каждой горизонтной семьи, включая обе модификации. На основном горизонте $h=1$ после поправки Holm ни одно сравнение скользящих процедур не отвергает равенства средних потерь при уровне 5%, как при четырёх, так и при восьми лагах HAC. В объединённой M2_clip_g конфигурации разность NFCI минус AR + ESI равна 0,0344 с обычным 95%-м асимптотическим интервалом [−0,1301; 0,1988]; для ANFCI — 0,0493 с интервалом [−0,0801; 0,1787]. Оба интервала включают нуль и различия обоих знаков. Поэтому наблюдаемый проигрыш на полной выборке не превращается в доказанное равенство или строго установленное ухудшение ожидаемого качества.[^24]'
changes[123]='На дополнительном горизонте $h=4$ при четырёх лагах HAC минимальное скорректированное p-значение составляет 0,0676; отвержений на уровне 5% нет. При восьми лагах два сравнения ANFCI с HIST в конфигурациях Q_raw и Q_clip_g дают положительные разности и скорректированные p-значения 0,0126 и 0,0406. Эти результаты благоприятны для HIST и чувствительны к настройке долговременной дисперсии. Преимущества американских расширений над ориентирами после указанной поправки не подтверждено. Все исходные p-значения, обычные и одновременные интервалы представлены в приложении; прежние отдельные семьи тестов сохранены как история первоначального анализа.[^24]'
changes[124]='Эти статистики остаются асимптотическими и используют лишь 58 или 55 дат. Четыре конфигурации не увеличивают число независимых экономических наблюдений. Перекрытие целей, неоднородность эпизодов и пересмотры ограничивают надёжность вывода; объединение сравнений и публикация интервалов не устраняют этих свойств данных. Результаты rolling52 не переносятся на расширяющееся окно. Уточнение статистической части состоит в явном измерении неопределённости и учёте всей новой семьи сравнений, а не в искусственном получении значимого превосходства.'
changes[125]='Международно-экономическая интерпретация теперь опирается на две конкретные проверки. Сохранение исходного среднего выигрыша при M2 показывает, что он не требует недельных наблюдений третьего месяца. Исчезновение выигрыша после ограничения лагового роста связывает его с устройством европейского прогноза и его реакцией на крайние состояния. Это разграничивает наличие международных финансовых взаимосвязей и способность конкретного индекса улучшать достаточно устойчивую базовую процедуру. Пересечение информации индексов с ESI и различная реакция стран еврозоны остаются возможными объяснениями, отдельно не идентифицированными в данной модели. Полученный результат относится к способу прогнозного использования финансовой информации и не опровергает трансграничные механизмы, рассмотренные в первой главе.[^25]'
changes[126]='Ответ на первый исследовательский вопрос оказывается условным: на полной выборке оба индекса улучшают исходную AR + ESI, в том числе при сокращённом временном охвате, но это преимущество исчезает после ограничения экстраполяции по лаговому росту. На второй вопрос ответ также требует уточнения: американские расширения не превосходят HIST, однако после изменения реакции на рост отдельные европейские процедуры имеют меньшую среднюю потерю, чем он. В прямом сравнении индексов ANFCI сохраняет более благоприятные описательные свойства на четырёхквартальном горизонте в новых проверках, но поздние версии способны изменить ранжирование. Устойчивое статистически подтверждённое преимущество американского индекса перед европейской базой или простым ориентиром не установлено.'
changes[127]='Вклад главы состоит в сопоставлении NFCI и ANFCI в общем историческом календаре и в проверке того, насколько их дополнительная прогнозная ценность зависит от версии данных, временного охвата и устойчивости европейской базы к экстраполяции. Диагностика показывает, что относительный выигрыш финансового расширения может отражать компенсацию слабого места базовой регрессии. Практическое следствие — сопоставлять внешний финансовый сигнал с простыми и проверенными на экстремальных предикторах ориентирами, одновременно отслеживая потери, нарушения границы и доступность информации. В третьей главе эти результаты используются для рекомендаций по мониторингу рисков роста еврозоны. Само правило ограничения рассматривается как проверенный здесь диагностический вариант, а не как готовая универсальная замена прогнозной системы.'

changes[152]='[^24]: Вспомогательные статистические сравнения обновлены по revision25/results/rolling52_inference.csv; полная матрица — chapter2/Appendix_Chapter_2_Additional_Experiments.md. Пять пар для каждой из четырёх конфигураций дают двадцать сравнений на горизонт. Holm применяется отдельно для h=1 и h=4 и для каждой фиксированной длины HAC; основная спецификация — h=1, L=4. Обычные интервалы индивидуальные; интервалы Bonferroni учитывают двадцать сравнений соответствующей семьи. Прежние результаты revision19/results/ANFCI_GW_rolling52.csv и revision18/results/pilot_GW_rolling52.csv сохраняются, но их отдельные семейства не смешиваются с новой общей поправкой. Общий контроль всех решений за историю проекта не заявляется.'
after[153]=['[^26]: Дополнительный эксперимент: revision25/PROTOCOL.md, run_checks.py и результаты в revision25/results. Правила сформулированы 18 октября 2026 года до просмотра новых результатов; расчёт в текущей редакции выполнен 19 октября. Сохранены четыре конфигурации, два окна, оба горизонта и все пять моделей — 4 520 строк прогнозов, включая 1 130 воспроизведённых исходных. Это повторные процедуры на тех же 58/55 оценочных датах, а не увеличение независимой выборки. Проверки временного охвата и ограничения роста имеют ретроспективный диагностический статус. Полные таблицы и детали — chapter2/Appendix_Chapter_2_Additional_Experiments.md.']
changes[154]='Электронные описания источников данных проверены 17 октября 2026 года. Основной эксперимент и редакции главы сохранены в исследовательском архиве. Дополнительные расчёты, их проверка и содержательное обновление главы выполнены 19 октября 2026 года; исходные данные и результаты прежних этапов не перезаписывались.'

